        .feedback-card-inline { border-radius: 8px; margin-top: 25px; border-left: 5px solid; animation: fadeIn 0.5s; }
        .feedback-card-inline.correct { background-color: #f0fff4; border-color: var(--success-color); }
        .feedback-card-inline.incorrect { background-color: #fff5f5; border-color: var(--danger-color); }
        .feedback-card-inline .feedback-card-header { padding: 10px 15px; display: flex; align-items: center; gap: 10px; font-weight: bold; }
        .feedback-card-inline .feedback-card-header .fa-check-circle { color: var(--success-color); }
        .feedback-card-inline .feedback-card-header .fa-times-circle { color: var(--danger-color); }
        .feedback-card-inline .feedback-card-body { padding: 0 15px 15px; }
        .feedback-card-inline .feedback-card-body p { margin-bottom: 0; }
        .feedback-card-inline .feedback-card-body ul, .feedback-card-inline .feedback-card-body ol { margin-left: 20px; }

        /* --- MODAL STYLES --- */
        .modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.6); z-index: 2000; display: none; justify-content: center; align-items: center; animation: fadeIn 0.3s; }
        .modal-content { background: white; padding: 30px; border-radius: 12px; width: 90%; max-width: 500px; box-shadow: 0 10px 30px rgba(0,0,0,0.2); text-align: center; }
        .modal-content h3 { margin-top: 0; color: var(--hin-blue); font-family: var(--font-heading); }
        .modal-content .blank-input { border: none; border-bottom: 2px solid var(--light-text-color); font-size: 1rem; padding: 8px 0; width: 100%; transition: border-color 0.3s; background: transparent; }
        .modal-content .blank-input:focus { border-color: var(--hin-blue); outline: none; }
        .modal-actions { margin-top: 25px; display: flex; justify-content: center; gap: 10px; }
        #congrats-modal .modal-icon { font-size: 4rem; color: var(--hin-gold-dark); margin-bottom: 15px; }

        /* TOAST NOTIFICATION */
        .toast-notification {
            position: fixed; top: 20px; right: 20px; background-color: var(--hin-blue); color: white;
            padding: 15px 25px; border-radius: 8px; box-shadow: 0 4px 15px rgba(0,0,0,0.2);
            z-index: 9999; font-weight: 500;
            animation: slideInToast 0.5s ease forwards, slideOutToast 0.5s ease 3.5s forwards;
        }
        .toast-notification.warning { background-color: var(--hin-gold-dark); color: var(--hin-blue); }
        @keyframes slideInToast { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
        @keyframes slideOutToast { from { transform: translateX(0); opacity: 1; } to { transform: translateX(100%); opacity: 0; } }

        /* --- OPEN CLOZE (FILL IN BLANKS) STYLES --- */
        .open-cloze-container { font-size: 1.1rem; line-height: 2.2; }
        .open-cloze-container input {
            width: 120px;
            border: none;
            border-bottom: 2px dotted var(--light-text-color);
            background: transparent;
            text-align: center;
            font-size: 1.1rem;
            margin: 0 5px;
            padding: 2px 0;
        }
        .open-cloze-container input:focus {
            outline: none;
            border-bottom-style: solid;
            border-bottom-color: var(--hin-blue);
        }

        /* --- IMPROVED SENTENCE TRANSFORM STYLES --- */
        .sentence-transform-container { margin-top: 15px; background: #f8f9fa; padding: 20px; border-radius: 8px; }
        .sentence-transform-container .transform-line { display: flex; align-items: baseline; gap: 8px; font-size: 1.1rem; flex-wrap: wrap; }
        .sentence-transform-container input { flex-grow: 1; min-width: 150px; text-align: center; border: none; border-bottom: 2px dotted var(--light-text-color); font-size: 1.1rem; padding: 5px 0; background: transparent; transition: border-color 0.3s; }
        .sentence-transform-container input:focus { border-bottom-style: solid; border-bottom-color: var(--hin-blue); outline: none; }

        /* --- IMPROVED ERROR CORRECTION STYLES --- */
        .error-correction-container { margin-top: 15px; display: grid; grid-template-columns: 1fr; gap: 20px; }
        .error-correction-container .input-group { display: flex; flex-direction: column; }
        .error-correction-container label { font-weight: 500; margin-bottom: 5px; color: var(--hin-blue); }
        .error-correction-container input { width: 100%; padding: 10px; font-size: 1rem; border: 1px solid var(--border-color); border-radius: 6px; }
        @media (min-width: 768px) { .error-correction-container { grid-template-columns: 1fr 2fr; } }

        /* --- DRAG & DROP MATCHING STYLES (DESKTOP) --- */
        .matching-drag-drop-container { display: flex; gap: 20px; flex-wrap: wrap; margin-top: 20px; }
        .matching-column { flex: 1; min-width: 250px; }
        .matching-column h4 { margin-bottom: 10px; color: var(--hin-blue); border-bottom: 2px solid var(--border-color); padding-bottom: 5px; }
        .drop-zone-list, .draggable-list { list-style: none; padding: 0; }
        .drop-zone { display: flex; align-items: center; gap: 10px; border: 2px dashed var(--border-color); padding: 10px; margin-bottom: 10px; border-radius: 8px; background-color: #f8f9fa; transition: all 0.2s ease; min-height: 50px; }
        .drop-zone.over { background-color: #fffbeb; border-color: var(--hin-gold); }
        .drop-zone .placeholder { color: #aaa; font-style: italic; flex-grow: 1; text-align: center; }
        .drop-zone .dropped-item { background-color: var(--active-bg); border: 1px solid var(--border-color); padding: 5px 10px; border-radius: 6px; flex-grow: 1; text-align: left; word-break: break-word; }
        .draggable-item { background: white; padding: 10px; margin-bottom: 10px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.1); cursor: grab; transition: all 0.2s ease; border: 1px solid var(--border-color); }
        .draggable-item:active { cursor: grabbing; }
        .draggable-item.dragging { opacity: 0.5; box-shadow: 0 4px 10px rgba(0,0,0,0.2); }
        .draggable-item.used { opacity: 0.4; cursor: not-allowed; background-color: #f0f0f0; }

        /* --- CLICK & DROP STYLES (MOBILE) --- */
        .draggable-item.mobile-selected { border-color: var(--hin-blue); background-color: var(--active-bg); box-shadow: 0 0 0 3px var(--hin-blue); font-weight: bold; }
        .is-mobile .draggable-item { cursor: pointer; }

        /* --- FOOTER --- */
        .main-footer {
            background-color: var(--hin-blue);
            color: white;
            padding: 40px 5%;
            text-align: center;
            margin-top: 40px;
        }
        .footer-content {
            max-width: 800px;
            margin: 0 auto;
        }
        .footer-logo {
            font-family: var(--font-heading);
            font-weight: 900;
            font-size: 2.5rem;
            margin-bottom: 10px;
        }
        .footer-logo span { color: var(--hin-gold-dark); }
        .footer-tagline {
