            color: #ccc;
            margin-bottom: 25px;
        }
        .footer-links {
            display: flex;
            justify-content: center;
            gap: 20px;
            margin-bottom: 25px;
        }
        .footer-links a {
            color: white;
            font-size: 1.8rem;
