        }
        .footer-links a:hover {
            transform: scale(1.2);
            color: var(--hin-gold);
        }
        .footer-contact p {
            margin: 5px 0;
            color: #ccc;
        }
        .footer-contact strong { color: white; }

        /* --- RESPONSIVE MEDIA QUERIES (IMPROVED) --- */
        @media (max-width: 991.98px) {
            .hamburger-btn { display: block; } .page-title { display: none; }
            .sidebar-menu { position: fixed; top: 0; left: -300px; width: 280px; height: 100%; z-index: 1100; border-radius: 0; overflow-y: auto; box-shadow: 0 0 20px rgba(0,0,0,0.2); }
            .sidebar-menu.open { left: 0; }
        }

        @media (max-width: 768px) {
            /* General Layout */
            main { padding: 80px 3% 40px; display: block; }
            .activity-container { padding: 20px 15px; }

            /* Header */
            .logo { font-size: 1.5rem; }
            .page-title { display: block; font-size: 0.9rem; max-width: 180px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-left: auto; text-align: right;}

            /* Tables for Theory - Add scroll */
            .theory-card .card-body table { display: block; overflow-x: auto; white-space: nowrap; }

            /* Stage Hero */
            .stage-hero { flex-direction: column; align-items: center; text-align: center; padding: 20px; }
            .stage-hero-progress { width: 100%; text-align: center; margin-top: 15px; }

            /* Questions & Inputs */
            .matching-drag-drop-container { flex-direction: column; }
            .matching-column { width: 100%; margin-bottom: 15px; }
            input[type="text"], input[type="password"], textarea { font-size: 16px !important; } /* Prevent iOS zoom */

            /* Quiz Navigation */
            .quiz-navigation { flex-direction: column-reverse; gap: 15px; }
            .quiz-navigation .control-btn, .quiz-navigation .start-btn { width: 100%; justify-content: center; }
            .quiz-navigation .action-center { width: 100%; margin: 5px 0; }

            /* Breadcrumbs */
            .breadcrumb-list { padding: 10px; font-size: 0.8rem; justify-content: center; }
            .breadcrumb-item { padding: 2px 0; }

            /* Modals */
            .modal-content { width: 95%; max-height: 85vh; padding: 20px; overflow-y: auto; }

