            .theory-card.active .card-body { padding: 15px; }
            .intro-list li { flex-direction: column; align-items: center; text-align: center; }
            #activity-introduction .intro-list::before { left: 50%; display: none; } /* Remove vertical line on mobile */

            /* Footer */
            .footer-links a { font-size: 1.5rem; }
            .footer-logo { font-size: 1.8rem; }
        }
    </style>
