        window.addEventListener("message", (event) => {
            if (event.data && event.data.type === 'HIN_CONFIG') {
                console.log("Đã nhận cấu hình từ HIN:", event.data, 'origin=', event.origin);
                window.__HIN_PARENT_ORIGIN = event.origin || '*';
                try { event.source?.postMessage({ type: 'HIN_CONFIG_ACK', status: 'ok' }, event.origin || '*'); } catch(e){ /*ignore*/ }

                const config = event.data;
                document.getElementById('student-name').value = config.studentName || '';
                document.getElementById('student-class').value = config.className || '';
                studentInfo.studentId = config.studentId || 'unknown';
                studentInfo.assignmentId = config.assignmentId || 'unknown';
