        async function sendResultsToHin() {
            if (resultsSubmitted) return;
            resultsSubmitted = true;
            saveProgressToLocalStorage(); 

            const endTime = new Date();
            const durationSeconds = startTime ? Math.round((new Date() - startTime) / 1000) : 0;
            const submittedAt = endTime.toISOString();

            let detailedFeedback = [];
            if (quizStates.stage2.feedback) {
                quizStates.stage2.feedback.forEach(fb => {
                    if (!fb.is_correct) {
                        const qData = quizStates.stage2.flatQuestions[fb.question_number - 1];
                        detailedFeedback.push({
                            stage: 'Giai đoạn 2: Kiểm tra Lý thuyết',
                            question_number: fb.question_number,
                            question: qData.question,
                            studentAnswer: fb.student_answer,
                            aiExplanation: fb.explanation
                        });
                    }
                });
            }
            if (quizStates.stage3.feedback) {
                quizStates.stage3.feedback.forEach(fb => {
                    if (!fb.is_correct) {
                        const qData = quizStates.stage3.flatQuestions[fb.question_number - 1];
                        let questionText = qData.question || qData.instruction;
                        if(qData.sentence) questionText += ` (${qData.sentence})`;
                        detailedFeedback.push({
                            stage: 'Giai đoạn 3: Bài kiểm tra Thực hành',
                            question_number: fb.question_number,
                            question: questionText,
                            studentAnswer: fb.student_answer,
                            aiExplanation: fb.explanation
                        });
                    }
                });
            }

            const payload = {
                assignmentId: studentInfo.assignmentId,
                studentId: studentInfo.studentId,
                studentName: studentName,
                className: studentClass,
                assignmentTitle: lessonTitle,
                status: 'completed',
                submittedAt: submittedAt,
                timeSpentSeconds: durationSeconds,
                score: Math.round((userProgress.stage2_score + userProgress.stage3_score) / 2),
                stage2Score: userProgress.stage2_score,
                stage3Score: userProgress.stage3_score,
                detailedFeedback: detailedFeedback
            };

            const results = { type: 'HIN_EXERCISE_RESULT', payload: payload };
            const parentOrigin = window.__HIN_PARENT_ORIGIN || '*';

            const tryPostMessage = async () => {
                if (window.opener && !window.opener.closed) {
                    try {
                        window.opener.postMessage(results, parentOrigin);
                        console.log('Đã cố gắng postMessage tới parent:', parentOrigin, results);
                        return await new Promise((resolve) => {
                            let acked = false;
                            const onMsg = (ev) => { if (ev.data && ev.data.type === 'HIN_EXERCISE_RESULT_ACK') { acked = true; window.removeEventListener('message', onMsg); resolve({ ok: true }); } };
                            window.addEventListener('message', onMsg);
                            setTimeout(() => { if (!acked) { window.removeEventListener('message', onMsg); resolve({ ok: false, reason: 'no_ack' }); } }, 2000);
                        });
                    } catch (err) { console.warn('postMessage error', err); return { ok: false, reason: 'postMessage_error' }; }
                } else { return { ok: false, reason: 'no_opener' }; }
            };

            const postRes = await tryPostMessage();
            if (postRes.ok) {
                console.log('Parent ACK received.');
                showToast('Kết quả đã gửi về hệ thống HIN.');
                return;
            }

            console.warn('Parent did not ACK, fallback to server POST. reason=', postRes.reason);
            const fallbackUrl = (parentOrigin && parentOrigin !== '*') ? `${parentOrigin}/api/external-exercise-result` : '/api/external-exercise-result';
            try {
                const resp = await fetch(fallbackUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(results) });
                if (resp.ok) { showToast('Kết quả đã lưu về server (fallback).'); } 
                else { alert('Hoàn thành bài học nhưng không thể gửi kết quả tự động. Vui lòng liên hệ quản trị.'); }
            } catch (err) { alert('Hoàn thành bài học nhưng không thể gửi kết quả tự động. Vui lòng liên hệ quản trị.'); }
        }

        // =======================================================================
        // === START: CƠ CHẾ GỬI VỀ GOOGLE SHEET ĐÃ ĐƯỢỢC CẬP NHẬT
