        async function submitResultsToSheet(isPassed) {
            // Chỉ gửi khi có tên học sinh và URL đã được cấu hình
            if (!studentName || SCRIPT_URL === 'URL_GOOGLE_APPS_SCRIPT_CUA_BAN') {
                console.log("Thông tin học sinh hoặc SCRIPT_URL chưa có, bỏ qua việc gửi lên Google Sheet.");
                return;
            }

            // 1. TỔNG HỢP BÀI LÀM CHI TIẾT (Giữ nguyên)
            const detailedSubmission = {
                stage2: {
                    score: userProgress.stage2_score,
                    passed: userProgress.stage2_theory_quiz_passed,
                    questions: []
                },
                stage3: {
                    score: userProgress.stage3_score,
                    passed: userProgress.stage3_assessment_passed,
                    questions: []
                }
            };

            if (quizStates.stage2.flatQuestions) {
                quizStates.stage2.flatQuestions.forEach((q, index) => {
                    detailedSubmission.stage2.questions.push({
                        questionNumber: index + 1, part: q.part, type: q.type,
                        questionText: q.question || q.instruction,
                        studentAnswer: quizStates.stage2.answers[index] || "Chưa trả lời",
                        correctAnswer: q.answer,
                        isCorrect: quizStates.stage2.feedback?.find(fb => fb.question_number === index + 1)?.is_correct ?? null
                    });
                });
            }

            if (quizStates.stage3.flatQuestions) {
                quizStates.stage3.flatQuestions.forEach((q, index) => {
                    detailedSubmission.stage3.questions.push({
                        questionNumber: index + 1, part: q.part, type: q.type,
                        questionText: q.question || q.instruction,
                        studentAnswer: quizStates.stage3.answers[index] || "Chưa trả lời",
                        correctAnswer: q.answer,
                        isCorrect: quizStates.stage3.feedback?.find(fb => fb.question_number === index + 1)?.is_correct ?? null
                    });
                });
            }

            // 2. TẠO GÓI DỮ LIỆU (PAYLOAD) DẠNG OBJECT
            const payload = {
                timestamp: new Date().toISOString(),
                name: studentName,
                class: studentClass,
                duration: startTime ? Math.round((new Date() - startTime) / 1000) : 0,
                status: isPassed ? 'ĐẠT' : 'CHƯA ĐẠT',
                lesson: lessonTitle,
                stage2Score: userProgress.stage2_score,
                stage3Score: userProgress.stage3_score,
                averageScore: Math.round((userProgress.stage2_score + userProgress.stage3_score) / 2),
                submissionDetails: detailedSubmission // Gửi object chi tiết
            };

            // 3. GỬI DỮ LIỆU DƯỚI DẠNG CHUỖI JSON ĐỂ BYPASS CORS
            try {
                // Sử dụng 'Content-Type': 'text/plain' để tránh "preflight request" (OPTIONS) gây lỗi CORS.
                // Google Apps Script cần được cấu hình để parse chuỗi JSON này từ e.postData.contents.
                const response = await fetch(SCRIPT_URL, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'text/plain;charset=utf-8',
                    },
                    body: JSON.stringify(payload)
                });

                // Mặc dù response có thể không đọc được trực tiếp, ta vẫn giả định là thành công nếu không có lỗi mạng.
                console.log('Đã gửi kết quả lên Google Sheet thành công (đã bypass CORS).');
                showToast('Đã lưu kết quả của bạn.');

            } catch (error) {
                // Lỗi này thường chỉ xảy ra khi mất mạng hoặc URL của script bị sai.
                console.error('Lỗi mạng hoặc lỗi khi gửi dữ liệu:', error);
                showToast('Lỗi mạng, không thể lưu kết quả.', 'warning');
            }
        }
