        async function testApiKey(apiKey) {
            if (!apiKey) return false;
            const testModel = 'gemini-1.5-flash-latest'; 
            const url = `https://generativelanguage.googleapis.com/v1beta/models/${testModel}:generateContent?key=${apiKey}`;
            try {
                const response = await fetch(url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        contents: [{ parts: [{ text: "test" }] }],
                    })
                });
                return response.ok;
            } catch (error) {
                console.error("API Key test failed:", error);
                return false;
            }
        }

        async function handleLoginAndStart() {
            const startBtn = document.getElementById('start-learning-btn');
            const nameInput = document.getElementById('student-name');
            const classInput = document.getElementById('student-class');
            const keyInput = document.getElementById('api-key-input');
            const errorP = document.getElementById('api-key-error');

            const jumpStageSelect = document.getElementById('jump-stage-select');
            const jumpPasswordInput = document.getElementById('jump-password');

            studentName = nameInput.value.trim();
            studentClass = classInput.value.trim();
            const userApiKey = keyInput.value.trim();
            const targetStage = jumpStageSelect.value;
            const jumpPassword = jumpPasswordInput.value;

            if (!studentName) {
                errorP.textContent = 'Vui lòng nhập đầy đủ Họ và Tên.';
                errorP.style.display = 'block';
                return;
            }

            startBtn.disabled = true;
            startBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Đang xử lý...';
            errorP.style.display = 'none';

            if (userApiKey) {
                const isKeyValid = await testApiKey(userApiKey);
                if (isKeyValid) {
                    API_KEYS.unshift(userApiKey); 
                    showToast("Đã thêm API Key cá nhân của bạn.");
                } else {
                    showToast("API Key cá nhân không hợp lệ, sẽ dùng key chung.", "warning");
                }
            }

            currentApiKeyIndex = 0;
            startTime = new Date();

            saveProgressToLocalStorage(); 

            if (jumpPassword === SKIP_PASSWORD && targetStage) {
                if (targetStage === 'stage2') {
                    userProgress.stage1_theory_read = true;
                } else if (targetStage === 'stage3') {
                    userProgress.stage1_theory_read = true;
                    userProgress.stage2_theory_quiz_passed = true;
                }

                document.getElementById('student-info-modal').style.display = 'none';
                runApp();

                const targetId = `activity-${targetStage === 'stage2' ? 'theory-quiz' : 'final-assessment'}`;
                navigateToView(targetId);

                showToast(`Đã nhảy thành công đến ${jumpStageSelect.options[jumpStageSelect.selectedIndex].text}.`);

            } else {
                if (jumpPassword || targetStage) {
                     showToast("Mật khẩu hoặc lựa chọn nhảy không hợp lệ. Bắt đầu từ đầu.");
                }
                document.getElementById('student-info-modal').style.display = 'none';
                runApp();
            }
        }

