        function navigateToView(targetId) {
            const targetMenuItem = document.querySelector(`.menu-item[data-target="${targetId}"]`);
            if (!targetMenuItem || targetMenuItem.classList.contains('locked')) {
                showToast('Vui lòng hoàn thành giai đoạn trước để mở khóa.');
                return;
            }

            if (targetId === 'activity-theory-quiz' && !quizStates.stage2.isRendered) {
                renderQuiz('stage2');
            }
            if (targetId === 'activity-final-assessment' && !quizStates.stage3.isRendered) {
                renderQuiz('stage3');
            }

            sidebarMenuItems.forEach(i => i.classList.remove('active'));
            if(targetMenuItem) targetMenuItem.classList.add('active');

            activityViews.forEach(view => view.classList.toggle('active', view.id === targetId));

            updateBreadcrumb(targetId);

            if (window.innerWidth < 992) {
                closeMenu();
            }
        }

        function setupSidebarMenu() {
            hamburgerBtn.addEventListener('click', () => {
                sidebarMenu.classList.toggle('open');
                mobileOverlay.classList.toggle('visible');
            });

            const closeMenu = () => {
                sidebarMenu.classList.remove('open');
                mobileOverlay.classList.remove('visible');
