            mobileOverlay.addEventListener('click', closeMenu);

            sidebarMenuItems.forEach(item => {
                if (item.classList.contains('phase-divider')) return;
                item.addEventListener('click', (e) => {
                    e.preventDefault();
                    navigateToView(item.dataset.target);
                });
            });
