        function setupTheoryAccordion() {
            const theoryContainer = document.getElementById('theory-content-container');
            theoryContainer.addEventListener('click', function(e) {
                const header = e.target.closest('.card-header');
                if (header) {
                    const card = header.parentElement;
                    const isActive = card.classList.contains('active');

                    theoryContainer.querySelectorAll('.theory-card').forEach(c => c.classList.remove('active'));

                    if (!isActive) {
                        card.classList.add('active');
                    }
                }
