        function setupMiniQuizzes() {
            const container = document.getElementById('theory-content-container');
            container.addEventListener('change', (e) => {
                if (e.target.type === 'radio' && e.target.name.startsWith('mq')) {
                    const quizDiv = e.target.closest('.mini-quiz');
                    const feedbackDiv = quizDiv.querySelector('.mini-quiz-feedback');
                    const selectedValue = e.target.value;
                    const correctAnswer = feedbackDiv.dataset.correctAnswer;

                    feedbackDiv.style.display = 'block';
                    if (selectedValue === correctAnswer) {
