        function updateBreadcrumb(activeViewId) {
            if (!activeViewId) {
                const activeView = document.querySelector('.activity-view.active');
                if (activeView) activeViewId = activeView.id;
            }

            const breadcrumbItems = {
                1: document.getElementById('breadcrumb-1'),
                2: document.getElementById('breadcrumb-2'),
                3: document.getElementById('breadcrumb-3')
            };

            Object.values(breadcrumbItems).forEach(item => {
                item.classList.remove('active', 'unlocked');
            });

            breadcrumbItems[1].classList.add('unlocked');

            if (userProgress.stage1_theory_read) {
                 breadcrumbItems[2].classList.add('unlocked');
            }

            if (userProgress.stage2_theory_quiz_passed) {
                 breadcrumbItems[3].classList.add('unlocked');
            }

            if (activeViewId === 'activity-introduction') {
                breadcrumbItems[1].classList.add('active');
            } else if (activeViewId === 'activity-theory-quiz') {
                breadcrumbItems[2].classList.add('active');
            } else if (activeViewId === 'activity-final-assessment') {
                breadcrumbItems[3].classList.add('active');
            }
        }

        function isQuizActive() {
            return document.getElementById('activity-theory-quiz').classList.contains('active') ||
                   document.getElementById('activity-final-assessment').classList.contains('active');
        }

        function setupAntiCheat() {
            const handleCheatingAttempt = (event) => {
                if (event.type === 'paste' && (event.target.tagName !== 'INPUT' && event.target.tagName !== 'TEXTAREA')) {
                    return;
                }
                if (!antiCheatEnabled || !isQuizActive()) {
                    return;
                }
                cheatWarnings++;
                if (cheatWarnings === 1) {
                    alert('CẢNH BÁO LẦN 1:\nHệ thống phát hiện hành vi chuyển tab hoặc dán (paste).\n\nVi phạm lần thứ hai sẽ tự động HỦY BÀI LÀM của bạn.');
                } else if (cheatWarnings >= 2) {
                    forceReset("HÀNH VI GIAN LẬN BỊ PHÁT HIỆN. Bài làm của bạn đã bị hủy. Vui lòng làm lại từ đầu.");
                }
            };
            document.addEventListener('visibilitychange', () => {
                 if (document.visibilityState === 'hidden') {
                    handleCheatingAttempt({type: 'visibilitychange'});
                 }
            });
            window.addEventListener('paste', handleCheatingAttempt);
            document.getElementById('disable-cheat-btn').addEventListener('click', () => {
                const password = prompt("Chức năng chỉ dành cho giáo viên. Vui lòng nhập mật khẩu để tắt Chống gian lận:");
                if (password === SKIP_PASSWORD) {
                    antiCheatEnabled = false;
                    const btn = document.getElementById('disable-cheat-btn');
                    btn.textContent = "CGL: Đã tắt";
                    btn.style.color = 'var(--success-color)';
                    btn.style.borderColor = 'var(--success-color)';
                    alert("Chế độ Chống gian lận đã được vô hiệu hóa.");
                } else if (password !== null) {
                    alert("Mật khẩu không chính xác.");
                }
            });
        }

        function forceReset(message) {
            localStorage.removeItem(LOCAL_STORAGE_KEY);
            alert(message);
            location.reload();
        }

        function updateMenuLockState() {
            const menuLinks = {
                theoryQuiz: document.querySelector('[data-target="activity-theory-quiz"]'),
                finalAssessment: document.querySelector('[data-target="activity-final-assessment"]'),
            };
            const toggleLock = (el, lockEl, isLocked) => {
                if (el.classList.contains('locked') && !isLocked) {
                    lockEl.classList.add('unlocking');
                    setTimeout(() => {
                        el.classList.remove('locked');
                        lockEl.style.display = 'none';
                        lockEl.classList.remove('unlocking');
                    }, 600);
                } else {
                    el.classList.toggle('locked', isLocked);
                    lockEl.style.display = isLocked ? 'inline-block' : 'none';
                }
            };
            toggleLock(menuLinks.theoryQuiz, document.getElementById('lock-stage2'), !userProgress.stage1_theory_read);
            toggleLock(menuLinks.finalAssessment, document.getElementById('lock-stage3'), !userProgress.stage2_theory_quiz_passed);
        }

        function updateOverallProgress() {
            let completed = 0;
            if (userProgress.stage1_theory_read) completed++;
            if (userProgress.stage2_theory_quiz_passed) completed++;
            if (userProgress.stage3_assessment_passed) completed++;

            const progress = (completed / 3) * 100;
            document.getElementById('overall-progress-bar').style.width = `${progress}%`;
            document.getElementById('overall-progress-text').textContent = `${completed}/3 Giai đoạn`;
        }

        function handleSkipStage(stageId) {
             const password = prompt("Chức năng chỉ dành cho giáo viên. Vui lòng nhập mật khẩu để bỏ qua giai đoạn này:");
             if (password === SKIP_PASSWORD) {
                 if (stageId === 'stage2') {
                     userProgress.stage2_theory_quiz_passed = true;
                     userProgress.stage2_score = 100;
                     showCongratulationModal('Giai đoạn 2', 100, true);
                     navigateToView('activity-final-assessment');
                 } else if (stageId === 'stage3') {
                     userProgress.stage3_assessment_passed = true;
                     userProgress.stage3_score = 100;
                     showCongratulationModal('Hoàn thành bài học', 100, true);
                     sendResultsToHin();
                     submitResultsToSheet(true);
                 }
                 updateUIFromState();
                 saveProgressToLocalStorage();
             } else if (password !== null && password !== "") {
                 alert("Mật khẩu không chính xác!");
             }
         }

        // --- Quiz Rendering and Navigation ---
        function renderQuiz(stageId) {
            const state = quizStates[stageId];
            if (state.isRendered) return;

            const questionData = state.questions;
            let flatQuestions = [];

            for (const part in questionData) {
                questionData[part].forEach(q => {
                    flatQuestions.push({ ...q, part });
                });
            }

            state.totalQuestions = flatQuestions.length;
            state.flatQuestions = flatQuestions;
            let questionHtmls = [];
            const isMobile = window.innerWidth <= 768;


            flatQuestions.forEach((q, index) => {
                let instruction = q.instruction || q.part;
                let slideHtml = `<div class="quiz-question-slide" id="${stageId}-qslide${index}">
                                    <p><strong>Câu ${index + 1}/${state.totalQuestions}:</strong> (${q.part})</p>
                                    <p>${instruction}</p>`;

                if (q.imageUrl) {
                    slideHtml += `<div class="question-image-container" style="text-align: center; margin-bottom: 20px;">
                                    <img src="${q.imageUrl}" alt="Biểu đồ cho câu hỏi" style="max-width: 100%; height: auto; border-radius: 8px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);">
                                  </div>`;
                }

                switch (q.type) {
                    case 'mcq':
                    case 'tf':
                        slideHtml += `<div class="question-text">${q.question}</div><div class="mcq-options-visual">`;
                        if (q.type === 'mcq') {
                            const shuffledOptions = _.shuffle(q.options);
                            shuffledOptions.forEach((opt, i) => {
                                const originalOptIndex = q.options.indexOf(opt);
                                const originalLetter = String.fromCharCode(65 + originalOptIndex);
                                slideHtml += `<button class="mcq-option-btn" data-stage="${stageId}" data-qindex="${index}" data-value="${originalLetter}"><span class="option-letter">${String.fromCharCode(65 + i)}</span> ${opt}</button>`;
                            });
                        } else {
                            slideHtml += `<button class="tf-option-btn" data-stage="${stageId}" data-qindex="${index}" data-value="Đúng"><i class="fas fa-check"></i> Đúng</button>`;
                            slideHtml += `<button class="tf-option-btn" data-stage="${stageId}" data-qindex="${index}" data-value="Sai"><i class="fas fa-times"></i> Sai</button>`;
                        }
                        slideHtml += `</div>`;
                        break;
                    case 'fill':
                         slideHtml += `<div class="question-text">${q.question}</div>
                                      <div class="analysis-inputs"><input type="text" data-stage="${stageId}" data-qindex="${index}" placeholder="Nhập câu trả lời..."></div>`;
                        break;
                    case 'open_cloze':
                        const clozeHtml = q.paragraph.replace(/\((\d+)\)______/g, (match, number) => {
                            return `<input type="text" data-stage="${stageId}" data-qindex="${index}" data-subindex="${number}" placeholder="(${number})">`;
                        });
                        slideHtml += `<div class="open-cloze-container">${clozeHtml}</div>`;
                        break;
                    case 'error-correction':
                        slideHtml += `<div class="question-text">${q.sentence}</div>
                                      <div class="error-correction-container">
                                        <div class="input-group">
                                          <label for="error-input-${stageId}-${index}">Từ/Cụm từ sai:</label>
                                          <input type="text" id="error-input-${stageId}-${index}" data-stage="${stageId}" data-qindex="${index}" data-part="mistake" placeholder="Xác định lỗi sai">
                                        </div>
                                        <div class="input-group">
                                          <label for="correction-input-${stageId}-${index}">Viết lại câu đúng:</label>
                                          <input type="text" id="correction-input-${stageId}-${index}" data-stage="${stageId}" data-qindex="${index}" data-part="correction" placeholder="Viết lại cả câu">
                                        </div>
                                      </div>`;
                        break;

                    case 'matching':
                        const mobileClass = isMobile ? 'is-mobile' : '';
                        slideHtml += `<div class="matching-drag-drop-container ${mobileClass}" data-stage="${stageId}" data-qindex="${index}">
                                        <div class="matching-column">
                                            <h4>Câu hỏi</h4>
                                            <ul class="drop-zone-list">`;
                        q.left_items.forEach((item, i) => {
                            const itemNumber = item.split('.')[0];
                            slideHtml += `<li><div class="drop-zone" data-subindex="${itemNumber}"><span style="font-weight:bold;">${item}</span><span class="placeholder">${isMobile ? 'Nhấn để thả' : 'Thả vào đây'}</span></div></li>`;
                        });
                        slideHtml += `</ul></div><div class="matching-column"><h4>Lựa chọn</h4><ul class="draggable-list">`;
                        _.shuffle(q.right_items).forEach(item => {
                            const itemLetter = item.split('.')[0];
                            slideHtml += `<li class="draggable-item" draggable="${!isMobile}" data-value="${itemLetter}">${item}</li>`;
                        });
                        slideHtml += `</ul></div></div>`;
                        break;
                }
                slideHtml += `</div>`;
                questionHtmls.push(slideHtml);
            });

            document.getElementById(`${stageId}-content`).innerHTML = questionHtmls.join('');
            const actionsContainer = document.getElementById(`${stageId}-actions`);
            actionsContainer.style.display = 'block';
            actionsContainer.innerHTML = `<button class="control-btn" id="skip-${stageId}-btn"><i class="fas fa-forward"></i> Bỏ qua giai đoạn</button>`;
            document.getElementById(`skip-${stageId}-btn`).addEventListener('click', () => handleSkipStage(stageId));

            if (state.feedback) {
                state.feedback.forEach(fb => {
                    if (fb.is_correct) {
                        const qIndex = fb.question_number - 1;
                        const slide = document.getElementById(`${stageId}-qslide${qIndex}`);
                        if (slide) {
                            slide.classList.add('correct-locked');
                            const savedAnswer = state.answers[qIndex];
                            if(savedAnswer) {
                                const qData = state.flatQuestions[qIndex];
                                switch (qData.type) {
                                    case 'mcq': case 'tf':
                                        const btn = slide.querySelector(`.mcq-option-btn[data-value="${savedAnswer}"], .tf-option-btn[data-value="${savedAnswer}"]`);
                                        if (btn) btn.classList.add('selected');
                                        break;
                                    case 'fill':
                                        slide.querySelector(`input[data-qindex="${qIndex}"]`).value = savedAnswer;
                                        break;
                                    case 'error-correction':
                                        const [mistake, correction] = savedAnswer.split('|');
                                        slide.querySelector('[data-part="mistake"]').value = mistake || '';
                                        slide.querySelector('[data-part="correction"]').value = correction || '';
                                        break;
                                    case 'open_cloze':
                                        const parts = savedAnswer.split('|');
                                        parts.forEach((part, i) => {
                                            const input = slide.querySelector(`input[data-subindex="${i + 1}"]`);
                                            if (input) input.value = part;
                                        });
                                        break;
                                }
                            }
                        }
                    }
                });
            }

            let firstQuestionToShow = 0;
            if (state.feedback) {
                const firstIncorrect = state.feedback.find(fb => !fb.is_correct);
                if (firstIncorrect) {
                    firstQuestionToShow = firstIncorrect.question_number - 1;
                }
            }

            state.isRendered = true;
            setupQuizNavigation(stageId);
            showQuestion(stageId, firstQuestionToShow);
            setupAnswerSelection(stageId);
        }

        function setupQuizNavigation(stageId) {
            const navContainer = document.getElementById(`${stageId}-navigation`);
            navContainer.style.display = 'flex';
            navContainer.innerHTML = `
                <button class="control-btn" id="${stageId}-prev-btn"><i class="fas fa-arrow-left"></i> Câu trước</button>
                <button class="control-btn" id="${stageId}-next-btn">Câu tiếp theo <i class="fas fa-arrow-right"></i></button>
                <button class="start-btn" id="${stageId}-submit-btn" style="display: none;"><i class="fas fa-paper-plane"></i> Nộp bài</button>
            `;
            document.getElementById(`${stageId}-prev-btn`).addEventListener('click', () => navigateQuestion(stageId, -1));
            document.getElementById(`${stageId}-next-btn`).addEventListener('click', () => navigateQuestion(stageId, 1));
            document.getElementById(`${stageId}-submit-btn`).addEventListener('click', () => handleQuizSubmit(stageId));
        }

        function navigateQuestion(stageId, direction) {
            const state = quizStates[stageId];
            saveCurrentAnswer(stageId);
            const newIndex = state.currentQuestion + direction;
            if (newIndex >= 0 && newIndex < state.totalQuestions) {
                showQuestion(stageId, newIndex);
            }
        }

        function showQuestion(stageId, index) {
            const state = quizStates[stageId];
            state.currentQuestion = index;

            document.querySelectorAll(`#${stageId}-content .quiz-question-slide`).forEach(s => s.classList.remove('active'));
            const currentSlide = document.getElementById(`${stageId}-qslide${index}`);
            currentSlide.classList.add('active');

            const savedAnswer = state.answers[index];
            if (savedAnswer) {
                const qData = state.flatQuestions[index];
                switch (qData.type) {
                     case 'error-correction':
                        const [mistake, correction] = savedAnswer.split('|');
                        currentSlide.querySelector('[data-part="mistake"]').value = mistake || '';
                        currentSlide.querySelector('[data-part="correction"]').value = correction || '';
                        break;
                    case 'open_cloze':
                        const parts = savedAnswer.split('|');
                        parts.forEach((part, i) => {
                            const input = currentSlide.querySelector(`input[data-subindex="${i + 1}"]`);
                            if (input) input.value = part;
                        });
                        break;
                     case 'matching':
                        const matches = savedAnswer.split(',');
                        const draggableItems = document.querySelectorAll(`#${stageId}-qslide${index} .draggable-item`);
                        matches.forEach(match => {
                            const [subIndex, value] = match.split('-');
                            if(subIndex && value) {
                                const dropZone = currentSlide.querySelector(`.drop-zone[data-subindex="${subIndex}"]`);
                                const draggableItem = Array.from(draggableItems).find(item => item.dataset.value === value);
                                if (dropZone && draggableItem) {
                                     dropZone.innerHTML = `<span style="font-weight:bold;">${qData.left_items.find(i=>i.startsWith(subIndex))}</span><div class="dropped-item">${draggableItem.textContent}</div>`;
                                     dropZone.dataset.value = value;
                                     draggableItem.classList.add('used');
                                }
                            }
                        });
                        break;
                     default:
                        const inputs = currentSlide.querySelectorAll(`input[type="text"][data-qindex="${index}"]`);
                        if (inputs.length === 1) {
                            inputs[0].value = savedAnswer;
                        } else { 
                            const selectedBtn = currentSlide.querySelector(`[data-value="${savedAnswer}"]`);
                            if(selectedBtn) {
                                selectedBtn.parentElement.querySelectorAll('button').forEach(b => b.classList.remove('selected'));
                                selectedBtn.classList.add('selected');
                            }
                        }
                        break;
                }
            }

            const progress = ((index + 1) / state.totalQuestions) * 100;
            const progressBar = document.getElementById(`${stageId}-progress-bar`);
            const progressText = document.getElementById(`${stageId}-progress-text`);
            if (progressBar) progressBar.style.width = `${progress}%`;
            if (progressText) progressText.textContent = `Câu ${index + 1}/${state.totalQuestions}`;

            const isReviewMode = document.getElementById(`${stageId}-result`).style.display !== 'none';
            if (isReviewMode) {
                document.getElementById(`${stageId}-prev-btn-review`).disabled = (index === 0);
                document.getElementById(`${stageId}-next-btn-review`).disabled = (index === state.totalQuestions - 1);
            } else {
                document.getElementById(`${stageId}-prev-btn`).disabled = (index === 0);
                document.getElementById(`${stageId}-next-btn`).style.display = (index === state.totalQuestions - 1) ? 'none' : 'inline-flex';
                document.getElementById(`${stageId}-submit-btn`).style.display = (index === state.totalQuestions - 1) ? 'inline-flex' : 'none';
            }
            saveProgressToLocalStorage();
        }

        function saveCurrentAnswer(stageId) {
            const state = quizStates[stageId];
            const qIndex = state.currentQuestion;
            const slide = document.getElementById(`${stageId}-qslide${qIndex}`);
            if (!slide || slide.classList.contains('correct-locked')) return;

            const qData = state.flatQuestions[qIndex];
            switch (qData.type) {
                case 'error-correction':
                    const mistake = slide.querySelector('input[data-part="mistake"]').value.trim();
                    const correction = slide.querySelector('input[data-part="correction"]').value.trim();
                    state.answers[qIndex] = `${mistake}|${correction}`;
                    break;
                case 'open_cloze':
                    const clozeAnswers = [];
                    const inputs = slide.querySelectorAll(`input[data-qindex="${qIndex}"]`);
                    inputs.forEach(input => {
                        clozeAnswers[parseInt(input.dataset.subindex) - 1] = input.value.trim();
                    });
                    state.answers[qIndex] = clozeAnswers.join('|');
                    break;
                case 'matching':
                    const dropZones = slide.querySelectorAll('.drop-zone');
                    const answers = [];
                    dropZones.forEach(zone => {
                        if (zone.dataset.value) {
                            answers.push(`${zone.dataset.subindex}-${zone.dataset.value}`);
                        }
                    });
                    state.answers[qIndex] = answers.join(',');
                    break;
                case 'fill':
                    const singleInput = slide.querySelector(`input[data-qindex="${qIndex}"]`);
                    if (singleInput) state.answers[qIndex] = singleInput.value.trim();
                    break;
            }
        }

        function setupAnswerSelection(stageId) {
            const contentDiv = document.getElementById(`${stageId}-content`);

            contentDiv.addEventListener('click', (e) => {
                const btn = e.target.closest('.mcq-option-btn, .tf-option-btn');
                if (btn && btn.dataset.stage === stageId && !btn.closest('.correct-locked')) {
                    const qIndex = btn.dataset.qindex;
                    quizStates[stageId].answers[qIndex] = btn.dataset.value;
                    btn.parentElement.querySelectorAll('button').forEach(b => b.classList.remove('selected'));
                    btn.classList.add('selected');
                }
            });
            contentDiv.addEventListener('input', (e) => {
                const input = e.target.closest('input, textarea');
                if (input && input.dataset.stage === stageId && !input.closest('.correct-locked')) {
                    saveCurrentAnswer(stageId);
                }
            });

            const isMobile = window.innerWidth <= 768;
            if (isMobile) {
                setupMobileMatching(stageId, contentDiv);
            } else {
                setupDesktopMatching(stageId, contentDiv);
            }
        }

        function setupDesktopMatching(stageId, container) {
            let draggedItem = null;
            container.addEventListener('dragstart', (e) => {
                if (e.target.classList.contains('draggable-item') && !e.target.classList.contains('used') && !e.target.closest('.correct-locked')) {
                    draggedItem = e.target;
                    setTimeout(() => e.target.classList.add('dragging'), 0);
                }
            });
            container.addEventListener('dragend', (e) => {
                if(draggedItem) {
                    draggedItem.classList.remove('dragging');
                    draggedItem = null;
                }
            });
            container.addEventListener('dragover', (e) => {
                const dropZone = e.target.closest('.drop-zone');
                if (dropZone && !dropZone.closest('.correct-locked')) e.preventDefault();
            });
            container.addEventListener('dragenter', (e) => {
                const dropZone = e.target.closest('.drop-zone');
                if (dropZone && !dropZone.closest('.correct-locked')) dropZone.classList.add('over');
            });
            container.addEventListener('dragleave', (e) => {
                const dropZone = e.target.closest('.drop-zone');
                if (dropZone) dropZone.classList.remove('over');
            });
            container.addEventListener('drop', (e) => {
                const dropZone = e.target.closest('.drop-zone');
                if (dropZone && draggedItem && !dropZone.closest('.correct-locked')) {
                    e.preventDefault();
                    dropZone.classList.remove('over');

                    performDrop(stageId, dropZone, draggedItem);
                }
            });
        }

        function setupMobileMatching(stageId, container) {
            let mobileSelectedItem = null;
            container.addEventListener('click', (e) => {
                if(e.target.closest('.correct-locked')) return;

                const draggable = e.target.closest('.draggable-item');
                const dropZone = e.target.closest('.drop-zone');

                if (draggable && !draggable.classList.contains('used')) {
                     if (mobileSelectedItem) {
                        mobileSelectedItem.classList.remove('mobile-selected');
                    }
                    mobileSelectedItem = draggable;
                    mobileSelectedItem.classList.add('mobile-selected');
                } else if (dropZone && mobileSelectedItem) {
                    performDrop(stageId, dropZone, mobileSelectedItem);
                    mobileSelectedItem.classList.remove('mobile-selected');
                    mobileSelectedItem = null;
                }
            });
        }

        function performDrop(stageId, dropZone, itemToDrop) {
            const qIndex = dropZone.closest('.matching-drag-drop-container').dataset.qindex;
            const qData = quizStates[stageId].flatQuestions[qIndex];
            const subIndex = dropZone.dataset.subindex;

            if (dropZone.dataset.value) {
                 const oldItem = dropZone.closest('.matching-drag-drop-container').querySelector(`.draggable-item[data-value="${dropZone.dataset.value}"]`);
                 if (oldItem) oldItem.classList.remove('used');
            }

            const otherDropZone = dropZone.closest('.matching-drag-drop-container').querySelector(`.drop-zone[data-value="${itemToDrop.dataset.value}"]`);
            if (otherDropZone) {
                const oldQIndex = otherDropZone.closest('.matching-drag-drop-container').dataset.qindex;
                const oldQData = quizStates[stageId].flatQuestions[oldQIndex];
                const oldSubIndex = otherDropZone.dataset.subindex;
                otherDropZone.innerHTML = `<span style="font-weight:bold;">${oldQData.left_items.find(i=>i.startsWith(oldSubIndex))}</span><span class="placeholder">${window.innerWidth <= 768 ? 'Nhấn để thả' : 'Thả vào đây'}</span>`;
                delete otherDropZone.dataset.value;
            }

            dropZone.innerHTML = `<span style="font-weight:bold;">${qData.left_items.find(i=>i.startsWith(subIndex))}</span><div class="dropped-item">${itemToDrop.textContent}</div>`;
            dropZone.dataset.value = itemToDrop.dataset.value;
            itemToDrop.classList.add('used');

            saveCurrentAnswer(stageId);
        }

        // --- Submission and Feedback ---
        async function handleQuizSubmit(stageId) {
            saveCurrentAnswer(stageId); 
            const submitBtn = document.getElementById(`${stageId}-submit-btn`);
            const navContainer = document.getElementById(`${stageId}-navigation`);
            const resultContainer = document.getElementById(`${stageId}-result`);

            submitBtn.disabled = true;
            submitBtn.innerHTML = `<i class="fas fa-spinner fa-spin"></i> Đang chấm bài...`;
            navContainer.style.display = 'none';

            resultContainer.style.display = 'block';
            resultContainer.innerHTML = `<div class="loading-submission"><p>Vui lòng chờ trong giây lát. Hệ thống AI đang phân tích và chấm điểm bài làm của bạn...</p><div class="loading-bar-container"><div class="loading-bar-indeterminate"></div></div></div>`;
            resultContainer.scrollIntoView({ behavior: 'smooth', block: 'center' });

            const state = quizStates[stageId];

            // 1. Tính toán số câu đã làm đúng từ lần trước
            let previousCorrectCount = 0;
            if (state.feedback) {
                previousCorrectCount = state.feedback.filter(fb => fb.is_correct).length;
            }

            let userAnswers = [];
            state.flatQuestions.forEach((q, index) => {
                const isAlreadyCorrect = state.feedback?.find(fb => fb.question_number === index + 1)?.is_correct;
                if (!isAlreadyCorrect) {
                    let questionText = q.instruction || q.question || q.part;
                    if(q.sentence) questionText += ` (${q.sentence})`;

                    let answer_text = state.answers[index] || "Chưa trả lời";
                    if(q.type === 'open_cloze') answer_text = answer_text.split('|').map((a, i) => `(${i+1}: ${a})`).join(', ');

                    userAnswers.push({
                        question_number: index + 1,
                        question_type: q.type,
                        question: questionText,
                        correct_answer: Array.isArray(q.answer) ? q.answer.join('|') : q.answer,
                        student_answer: state.answers[index] || "Chưa trả lời"
                    });
                }
            });

            const prompt = `Bạn là một giáo viên tiếng Anh AI chuyên nghiệp, nghiêm khắc nhưng tận tình. Nhiệm vụ của bạn là chấm điểm bài làm ngữ pháp sau đây một cách chi tiết.

            THÔNG TIN BỐI CẢNH QUAN TRỌNG:
            - Đây có thể là bài làm lại (retry).
            - Tổng số câu hỏi của toàn bài: ${state.totalQuestions}
            - Số câu học sinh ĐÃ làm đúng ở lần trước (không gửi kèm ở danh sách này): ${previousCorrectCount}

            QUY TẮC CHẤM ĐIỂM:
            1. ĐIỂM SỐ: 
               - Chấm các câu trả lời mới trong danh sách 'userAnswers' bên dưới.
               - Tính toán số lượng câu đúng trong danh sách mới này. Gọi là NEW_CORRECT.
               - Tổng số câu đúng (TOTAL_CORRECT) = ${previousCorrectCount} + NEW_CORRECT.
               - Tính % điểm số cuối cùng = (TOTAL_CORRECT / ${state.totalQuestions}) * 100.
               - Điểm đạt là ${PASSING_SCORE}%.
            2. PHẢN HỒI CHO CÂU TRẢ LỜI ĐÚNG:
                - Khen ngợi học sinh.
                - Giải thích CẶN KẼ tại sao đáp án đó đúng về mặt ngữ pháp.
            3. PHẢN HỒI CHO CÂU TRẢ LỜI SAI:
                - Chỉ ra lỗi sai một cách rõ ràng.
                - Giải thích SIÊU CHI TIẾT tại sao nó sai.
                - Cung cấp một GỢI Ý MANG TÍNH HƯỚNG DẪN để học sinh tự suy luận ra đáp án đúng. TUYỆT ĐỐI KHÔNG CUNG CẤP ĐÁP ÁN ĐÚNG.
            4. NHẬN XÉT TỔNG QUAN: Viết một đoạn nhận xét ngắn gọn về bài làm, chỉ ra những điểm mạnh và những lỗi sai phổ biến mà học sinh cần cải thiện.
            5. ĐỊNH DẠNG ĐẦU RA: Trả về một đối tượng JSON duy nhất, không chứa markdown hay bất kỳ ký tự nào khác bên ngoài JSON.
            QUY TẮC PHỤ:
            - Với dạng 'fill' và dịch thuật, hãy linh hoạt chấp nhận các câu trả lời tương tự về mặt ngữ nghĩa và ngữ pháp, không quá cứng nhắc vào đáp án mẫu. Ví dụ "rise" và "increase" có thể thay thế cho nhau.
            - Với dạng bài viết mô tả biểu đồ, đáp án đúng là bất kỳ câu nào mô tả chính xác một xu hướng trong biểu đồ (ví dụ: nhiệt độ đạt đỉnh vào tháng 7, nhiệt độ giảm sau tháng 7, nhiệt độ ổn định từ tháng 10 đến tháng 12).
            BÀI LÀM LẦN NÀY CỦA HỌC SINH (CHỈ BAO GỒM CÁC CÂU LÀM LẠI):
            ${JSON.stringify(userAnswers, null, 2)}
            CẤU TRÚC JSON BẮT BUỘC:
            { "total_correct_count": <number>, "score": <number>, "passed": <boolean>, "summary": "<string: nhận xét>", "feedback": [ { "question_number": <number>, "student_answer": "<string>", "is_correct": <boolean>, "explanation": "<string: giải thích>" } ] }`;

            try {
                const geminiResponse = await callGeminiAPI(prompt);
                const result = JSON.parse(geminiResponse);

                if (state.feedback) {
                    const newFeedbackMap = new Map(result.feedback.map(fb => [fb.question_number, fb]));
                    const mergedFeedback = state.feedback.map(oldFb => 
                        newFeedbackMap.has(oldFb.question_number) ? newFeedbackMap.get(oldFb.question_number) : oldFb
                    );
                    result.feedback = mergedFeedback;
                } else {
                    state.feedback = result.feedback; // Lần đầu làm bài
                }

                userProgress[`${stageId}_score`] = result.score;
                displayFeedback(stageId, result);

                if (result.passed) {
                    if (stageId === 'stage2') {
                        userProgress.stage2_theory_quiz_passed = true;
                        showCongratulationModal('Giai đoạn 2', result.score);
                    } else if (stageId === 'stage3') {
                        userProgress.stage3_assessment_passed = true;
                        showCongratulationModal('Hoàn thành bài học', result.score);
                        await sendResultsToHin(); // Gửi về hệ thống HIN
                        await submitResultsToSheet(true); // Gửi về Google Sheet
                    }
                    updateUIFromState();
                } else {
                    userProgress.retryFails[stageId]++;
                    if (stageId === 'stage3') {
                        await submitResultsToSheet(false); // Gửi về Google Sheet khi chưa đạt
                    }
                }
                saveProgressToLocalStorage();

            } catch (error) {
                console.error("Lỗi khi chấm bài:", error);
                resultContainer.innerHTML = `<p style="color: var(--danger-color);"><strong>Đã xảy ra lỗi!</strong> Không thể kết nối đến dịch vụ chấm điểm AI. Vui lòng thử lại sau. <br><small>${error.message}</small></p>`;
                navContainer.style.display = 'flex';
                submitBtn.disabled = false;
                submitBtn.innerHTML = `<i class="fas fa-paper-plane"></i> Nộp bài`;
            }
        }

        function displayFeedback(stageId, result) {
            const resultContainer = document.getElementById(`${stageId}-result`);
            const scoreValue = Math.round(result.score);
            const fails = userProgress.retryFails[stageId] || 0;

            let summaryHtml = `
                <div class="result-summary">
                     <div class="score-display"><div class="score">${scoreValue}%</div></div>
                    <div class="status ${result.passed ? 'passed' : 'failed'}">${result.passed ? 'ĐẠT' : 'CHƯA ĐẠT'}</div>
                    <p>${result.summary}</p>
                    ${!result.passed ? `<div id="${stageId}-penalty-message" class="penalty-message"></div>` : ''}
                </div>`;
            resultContainer.innerHTML = summaryHtml;
            resultContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });

            result.feedback.forEach(fb => {
                const questionSlide = document.getElementById(`${stageId}-qslide${fb.question_number - 1}`);
                if (questionSlide) {
                    const oldFeedback = questionSlide.querySelector('.feedback-card-inline');
                    if (oldFeedback) oldFeedback.remove();

                    const feedbackHtml = `<div class="feedback-card-inline ${fb.is_correct ? 'correct' : 'incorrect'}"><div class="feedback-card-header"><i class="fas ${fb.is_correct ? 'fa-check-circle' : 'fa-times-circle'}"></i><h4>Nhận xét của giáo viên AI</h4></div><div class="feedback-card-body">${marked.parse(fb.explanation)}</div></div>`;
                    questionSlide.insertAdjacentHTML('beforeend', feedbackHtml);
                }
            });

            document.querySelectorAll(`#${stageId}-content input, #${stageId}-content textarea, #${stageId}-content button, #${stageId}-content .draggable-item`).forEach(el => {
                if (!el.closest('.correct-locked')) {
                     el.disabled = true;
                     el.style.cursor = 'default';
                     if(el.draggable) el.draggable = false;
                }
            });

            const navContainer = document.getElementById(`${stageId}-navigation`);
            navContainer.style.display = 'flex';
            navContainer.innerHTML = `<button class="control-btn" id="${stageId}-prev-btn-review"><i class="fas fa-arrow-left"></i> Câu trước</button><div class="action-center" id="${stageId}-action-center"></div><button class="control-btn" id="${stageId}-next-btn-review">Câu sau <i class="fas fa-arrow-right"></i></button>`;

            const actionCenter = document.getElementById(`${stageId}-action-center`);
            let retryButtonHtml = `<button class="control-btn" id="${stageId}-retry-btn-passed"><i class="fas fa-redo"></i> Làm lại từ đầu</button>`;

            if (result.passed) {
                if (stageId === 'stage2') {
                    actionCenter.innerHTML = retryButtonHtml + `<button class="start-btn" id="${stageId}-continue-btn">Tiếp tục <i class="fas fa-arrow-right"></i></button>`;
                    document.getElementById(`${stageId}-continue-btn`).addEventListener('click', () => navigateToView('activity-final-assessment'));
                } else if (stageId === 'stage3') {
                     actionCenter.innerHTML = `<p style="font-weight: bold; color: var(--success-color);">Bạn đã hoàn thành toàn bộ bài học!</p>` + retryButtonHtml;
                }
                 document.getElementById(`${stageId}-retry-btn-passed`).addEventListener('click', () => resetQuiz(stageId, 'full'));
            } else {
                const penaltySeconds = 10;
                actionCenter.innerHTML = `<button class="control-btn" id="${stageId}-retry-btn" disabled><i class="fas fa-redo"></i> Làm lại câu sai</button>`;

                const retryBtn = document.getElementById(`${stageId}-retry-btn`);
                const penaltyMsg = document.getElementById(`${stageId}-penalty-message`);
                penaltyMsg.textContent = `Bạn cần đọc lại phần chữa bài. Thời gian chờ để làm lại là ${penaltySeconds} giây.`;

                let timeLeft = penaltySeconds;
                if (penaltyTimer) clearInterval(penaltyTimer);
                penaltyTimer = setInterval(() => {
                    timeLeft--;
                    retryBtn.innerHTML = `<i class="fas fa-redo"></i> Làm lại câu sai (${timeLeft}s)`;
                    if (timeLeft <= 0) {
                        clearInterval(penaltyTimer);
                        retryBtn.disabled = false;
                        retryBtn.innerHTML = `<i class="fas fa-redo"></i> Làm lại câu sai`;
                        penaltyMsg.textContent = "Bạn có thể làm lại bài ngay bây giờ.";
                        retryBtn.addEventListener('click', () => resetQuiz(stageId, 'retry'));
                    }
                }, 1000);
            }

            document.getElementById(`${stageId}-prev-btn-review`).addEventListener('click', () => { showQuestion(stageId, quizStates[stageId].currentQuestion - 1); });
            document.getElementById(`${stageId}-next-btn-review`).addEventListener('click', () => { showQuestion(stageId, quizStates[stageId].currentQuestion + 1); });
            showQuestion(stageId, quizStates[stageId].currentQuestion);
        }

        function resetQuiz(stageId, mode = 'full') {
            const state = quizStates[stageId];

            if (mode === 'retry') {
                const newAnswers = {};
                if (state.feedback) {
                    state.feedback.forEach(fb => {
                        const qIndex = fb.question_number - 1;
                        if (fb.is_correct) {
                            newAnswers[qIndex] = state.answers[qIndex];
                        }
                    });
                }
                state.answers = newAnswers;
            } else { 
                state.answers = {};
                state.feedback = null;
                userProgress[`${stageId}_score`] = 0;
                userProgress.retryFails[stageId] = 0;
            }

            state.isRendered = false;
            document.getElementById(`${stageId}-result`).style.display = 'none';
            if (penaltyTimer) clearInterval(penaltyTimer);
            renderQuiz(stageId);
        }

        function showCongratulationModal(stageName, score, isSkipped = false) {
            const modal = document.getElementById('congrats-modal');
            const title = document.getElementById('congrats-title');
            const message = document.getElementById('congrats-message');
            if (isSkipped) {
                title.textContent = `Đã bỏ qua ${stageName}`;
                message.textContent = `Bạn đã sử dụng mật khẩu để tiếp tục. Hãy nhớ quay lại ôn tập nhé!`;
            } else {
                title.textContent = `Chúc mừng bạn!`;
                message.textContent = `Bạn đã hoàn thành ${stageName} với số điểm ${score}%. `;
            }
            modal.style.display = 'flex';
            document.getElementById('congrats-next-btn').onclick = () => { modal.style.display = 'none'; };
        }

        async function callGeminiAPI(promptContent) {
            for (let i = 0; i < API_KEYS.length; i++) {
                const apiKey = API_KEYS[currentApiKeyIndex];

                for (const modelName of MODELS) {
                    const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${apiKey}`;

                    try {
                        const response = await fetch(url, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                contents: [{ parts: [{ text: promptContent }] }],
                                generationConfig: { response_mime_type: "application/json" }
                            })
                        });

                        if (response.ok) {
                            console.log(`API call successful with Key Index: ${currentApiKeyIndex} and Model: ${modelName}`);
                            const data = await response.json();
                            return data.candidates[0].content.parts[0].text;
                        } else {
                             console.warn(`API Error for Key Index ${currentApiKeyIndex} with Model ${modelName}: ${response.status} ${response.statusText}`);
                        }
                    } catch (error) {
                        console.warn(`Network Error for Key Index ${currentApiKeyIndex} with Model ${modelName}:`, error);
                    }
                }

                console.log(`All models failed for Key Index ${currentApiKeyIndex}. Trying next key.`);
                showToast(`Key ${currentApiKeyIndex + 1} không hoạt động, thử key tiếp theo...`, 'warning');
                currentApiKeyIndex = (currentApiKeyIndex + 1) % API_KEYS.length;
            }

            throw new Error("Tất cả API keys và các mô hình đều không hoạt động.");
        }

        // --- State Management (LocalStorage) ---
        function saveProgressToLocalStorage() {
            if (!studentName) return; 
            const stateToSave = {
                studentName,
                studentClass,
                studentInfo,
                userProgress,
                quizStates,
                startTime: startTime.toISOString()
            };
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(stateToSave));
        }

        function loadProgressFromLocalStorage() {
            try {
                const savedState = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY));
                if (savedState) {
                    studentName = savedState.studentName;
                    studentClass = savedState.studentClass;
                    studentInfo = savedState.studentInfo;
                    userProgress = savedState.userProgress;
                    quizStates = savedState.quizStates;
                    startTime = new Date(savedState.startTime);
                    quizStates.stage2.isRendered = false;
                    quizStates.stage3.isRendered = false;
                    return true;
                }
            } catch (error) {
                console.error("Failed to load saved progress:", error);
                localStorage.removeItem(LOCAL_STORAGE_KEY);
            }
            return false;
        }

        function checkForSavedProgress() {
            if (loadProgressFromLocalStorage()) {
                document.getElementById('student-info-modal').style.display = 'none';
                const resumeModal = document.getElementById('resume-session-modal');
                resumeModal.style.display = 'flex';

                document.getElementById('resume-session-yes').onclick = () => {
                    resumeModal.style.display = 'none';
                    runApp();
                    const lastActiveStage = userProgress.stage2_theory_quiz_passed ? 'activity-final-assessment' : 'activity-theory-quiz';
                    navigateToView(lastActiveStage);
                    showToast("Đã khôi phục phiên làm bài của bạn.");
                };
                document.getElementById('resume-session-no').onclick = () => {
                    localStorage.removeItem(LOCAL_STORAGE_KEY);
                    location.reload();
                };
            }
        }

        function updateUIFromState() {
            updateMenuLockState();
            updateOverallProgress();
            updateBreadcrumb();
        }

        function showToast(message, type = '') {
            const toast = document.createElement('div');
            toast.textContent = message;
            toast.className = `toast-notification ${type}`;
            document.body.appendChild(toast);
            setTimeout(() => { toast.remove(); }, 4000);
        }

        // --- APPLICATION START ---
        initializeApplication(); 
    });
</script>
